{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Morphine, the closest structural analogue (Morgan 0.541), has an oral bioavailability of approximately 30% in humans, supporting F >= 20% for the query despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Codeine, a closely related N-methyl morphinan, has an oral bioavailability of 84 ± 5% (range 74–94%), providing strong supportive evidence that this scaffold can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Nalmefene, a structurally related morphinan, has an absolute oral bioavailability of about 53% with food, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Naltrexone, a 6-keto morphinan with N-cyclopropylmethyl and 14-hydroxy substitution, has very low oral bioavailability (~5%), but these structural differences and its extensive first-pass metabolism limit transferability to the N-methyl hydromorphone-like query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is hydromorphone, an N-methyl morphinan-6-one. The closest analogue morphine has F around 20–30%, while other N-methyl morphinans (codeine, diacetylmorphine) and related nalmefene show F values of 40–90%. Naltrexone's low F is tied to its N-cyclopropylmethyl/14-hydroxy substitution and extensive first-pass metabolism, which are not shared. Rifampin co-treatment may induce metabolism and reduce exposure, but no direct evidence indicates F would fall below 20%; the preponderance of transferable evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present in the evidence set.",
    "No experimental bioavailability data under rifampin co-treatment are available; the rifampin effect on UGT/P-gp-mediated first-pass metabolism is inferred rather than directly measured.",
    "Morphine bioavailability data are variable around the 20% threshold, adding uncertainty to the closest-analogue extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

